// Browser preview: the screens, played back from a snapshot of what the
// stand-in daemon says (fixture.json, generated by a Rust test). Loaded
// only when the page is NOT inside the Tauri app — for reviews and cloud
// sessions, which can't open the Mac window. Nothing here runs an agent.

import { emit } from "@tauri-apps/api/event";
import { mockIPC } from "@tauri-apps/api/mocks";
import type { AgentView } from "../bindings/AgentView";
import type { FileNode } from "../bindings/FileNode";
import type { MountsView } from "../bindings/MountsView";
import type { VolumeStat } from "../bindings/VolumeStat";
import type { CardView } from "../bindings/CardView";
import type { KnockView } from "../bindings/KnockView";
import type { MoveView } from "../bindings/MoveView";
import type { SpaceView } from "../bindings/SpaceView";
import type { LogEntry } from "../bindings/LogEntry";
import type { MachineView } from "../bindings/MachineView";
import type { SavedView } from "../bindings/SavedView";
import type { TabKind } from "../bindings/TabKind";
import type { TabView } from "../bindings/TabView";
import fixture from "./fixture.json";

type Chan = { onmessage: (e: unknown) => void };
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Args = Record<string, any>;

export const PREVIEW_HOST = "browser-preview";

export function installPreview() {
  const agents: AgentView[] = structuredClone(fixture.agents) as AgentView[];
  const logs: Record<string, LogEntry[]> = structuredClone(fixture.logs) as Record<string, LogEntry[]>;
  const machines: MachineView[] = structuredClone(fixture.machines) as MachineView[];
  // Per machine (by identity key): its files ("volume:path"), trees, and stats.
  const files = structuredClone(fixture.files) as Record<string, Record<string, string>>;
  const trees = structuredClone(fixture.trees) as Record<string, Record<string, FileNode[]>>;
  const stats = structuredClone(fixture.stats) as Record<string, Record<string, VolumeStat>>;
  const mounts = structuredClone(fixture.mounts) as Record<string, MountsView>;
  const machineKey = (p: { kind: string; address?: string; identity?: string }) => (p.kind === "outgoing" ? `outgoing:${p.address}` : `incoming:${p.identity}`);
  const machineOf = (p: { kind: string }) => machines.find((m) => machineKey(m.identity) === machineKey(p));
  const volumesOf = (p: { kind: string }) => machineOf(p)?.volumes ?? [];
  const views: SavedView[] = [];
  type SpaceRec = { view: SpaceView; moves: MoveView[]; invite: string | null };
  const spaceRecs: SpaceRec[] = structuredClone(fixture.spaces) as SpaceRec[];
  const knocks: KnockView[] = structuredClone(fixture.knocks) as KnockView[];
  const cards: CardView[] = structuredClone(fixture.cards) as CardView[];
  let cardCh: Chan | null = null;
  const spaceWatches = new Map<string, { id: string; ch: Chan }>();
  let knockCh: Chan | null = null;
  let moveN = 1000;
  const spaceOf = (id: string) => spaceRecs.find((r) => r.view.summary.id === id);
  const bump = (id: string) => {
    for (const w of spaceWatches.values()) if (w.id === id) w.ch.onmessage({ event: "updated", uri: "space://feed" });
  };
  const watches = new Map<string, { name: string; ch: Chan }>();
  const pending = new Map<string, { resolve: (v: unknown) => void; timer: number }>();
  let tabs: TabView[] = [];
  let focused: string | null = null;
  let generation = 0;
  let scope = 0;

  const keyOf = (tab: TabKind) => (tab.kind === "agent" ? `agent:${tab.name}` : tab.kind.replace("_", "-"));
  const snapshot = () => ({ generation, tabs, focused });
  const later = (fn: () => void) => setTimeout(fn, 0);
  const push = (name: string, entry: LogEntry) => {
    (logs[name] ??= []).push(entry);
    for (const w of watches.values()) if (w.name === name) w.ch.onmessage({ event: "entry", entry });
  };

  mockIPC(
    async (cmd: string, args: Args = {}) => {
      switch (cmd) {
        case "app_info":
          return { stand_in: true, contract_pin: fixture.contract_pin, stand_in_host: PREVIEW_HOST };
        case "actions_list":
          return fixture.actions;
        case "catalog_images":
          return fixture.catalog;
        case "catalog_check":
          return null;
        case "agents_list":
          return { agents, errors: [] };
        case "agents_create": {
          const input = args.input;
          if (agents.some((a) => a.name === input.name)) return { outcome: "in_use" };
          agents.push({ name: input.name, image_name: `diverge-agentic-loop-${input.image_kind}`, digest: "unbuilt", created: new Date().toISOString(), active: false, last_active: null, provider: null, logs_index: 0 });
          logs[input.name] = [];
          const view = (m: { provider?: unknown; volume_name: string; volume_relative_path: string; volume_mode: string; container_path: string }) => ({ ...m, provider: m.provider ?? null });
          mounts[input.name] = { pinned: input.provider, volume_mounts: input.volume_mounts.map(view), fuse_file_mounts: input.fuse_file_mounts.map(view), fuse_directory_mounts: input.fuse_directory_mounts.map(view) } as MountsView;
          return { outcome: "created" };
        }
        case "agents_delete": {
          const a = agents.find((x) => x.name === args.name);
          if (!a) return { outcome: "not_found" };
          if (a.active) return { outcome: "active" };
          agents.splice(agents.indexOf(a), 1);
          tabs = tabs.filter((t) => t.key !== `agent:${args.name}`);
          generation++;
          emit("tabs://changed", snapshot());
          return { outcome: "deleted" };
        }
        case "agents_mounts":
          return mounts[args.name] ?? null;
        case "agents_edit": {
          const input = args.input;
          const a = agents.find((x) => x.name === input.name);
          if (!a) return { outcome: "not_found" };
          if (a.active) return { outcome: "active" };
          const before = mounts[input.name];
          if (!before) return { outcome: "error", message: "not known here" };
          const view = (m: { provider?: unknown; volume_name: string; volume_relative_path: string; volume_mode: string; container_path: string }) => ({ ...m, provider: m.provider ?? null });
          mounts[input.name] = { pinned: before.pinned, volume_mounts: input.volume_mounts.map(view), fuse_file_mounts: input.fuse_file_mounts.map(view), fuse_directory_mounts: input.fuse_directory_mounts.map(view) } as MountsView;
          return { outcome: "edited" };
        }
        case "agents_message":
          return new Promise((resolve) => {
            const timer = window.setTimeout(() => {
              pending.delete(args.ticket);
              const list = logs[args.name] ?? [];
              push(args.name, { logs_index: (list[list.length - 1]?.logs_index ?? 0) + 1, created: new Date().toISOString(), item: { kind: "user_text", key: args.ticket, text: args.text } });
              resolve({ outcome: "delivered" });
            }, 2500);
            pending.set(args.ticket, { resolve, timer });
          });
        case "agents_message_take_back": {
          const p = pending.get(args.ticket);
          if (!p) return false;
          clearTimeout(p.timer);
          pending.delete(args.ticket);
          p.resolve({ outcome: "cancelled" });
          return true;
        }
        case "logs_open": {
          const id = `logs-${++scope}`;
          const q = args.query;
          const ch = args.onEvent as Chan;
          later(() => {
            for (const entry of logs[q.name] ?? []) {
              if (q.logs_index_from && entry.logs_index < q.logs_index_from) continue;
              if (q.logs_index_to && entry.logs_index > q.logs_index_to) continue;
              if (q.item_type && !matchesType(entry, q.item_type)) continue;
              ch.onmessage(q.jq ? { event: "value", value: "(jq runs in the app, not the browser preview)" } : { event: "entry", entry });
            }
            if (q.watch) watches.set(id, { name: q.name, ch });
            else ch.onmessage({ event: "end" });
          });
          return id;
        }
        case "scope_close":
          return watches.delete(args.id);
        case "volumes_list":
          return machineOf(args.machine) ? { outcome: "volumes", volumes: volumesOf(args.machine) } : { outcome: "error", message: "the daemon knows no machine by that identity" };
        case "volumes_stat": {
          const k = machineKey(args.machine);
          const v = volumesOf(args.machine).find((x) => x.name === args.name);
          if (!v) return { outcome: "error", message: `no volume named "${args.name}"` };
          const known = stats[k]?.[args.name];
          if (known && known.outcome === "error") return known;
          const used = Object.entries(files[k] ?? {}).filter(([p]) => p.startsWith(`${args.name}:`)).reduce((n, [, text]) => n + new TextEncoder().encode(text).length, 0);
          return { outcome: "stat", volume: v, bytes_used: used };
        }
        case "volumes_tree": {
          const k = machineKey(args.machine);
          const held = stats[k]?.[args.name];
          if (held && held.outcome === "error") return held;
          return trees[k]?.[args.name] ? { outcome: "tree", nodes: trees[k][args.name] } : { outcome: "error", message: `no volume named "${args.name}"` };
        }
        case "volumes_read": {
          const text = files[machineKey(args.machine)]?.[`${args.name}:${args.path}`];
          return text === undefined ? { outcome: "error", message: `${args.path}: not in the preview snapshot` } : { outcome: "text", text, bytes: new TextEncoder().encode(text).length };
        }
        case "volumes_write": {
          const k = machineKey(args.machine);
          (files[k] ??= {})[`${args.name}:${args.path}`] = args.text;
          return { outcome: "written" };
        }
        case "volumes_room":
          return { outcome: "capacity", bytes: 64 * 1024 ** 3 - volumesOf(args.machine).reduce((n, v) => n + v.bytes, 0) };
        case "volumes_room_for":
          return { outcome: "capacity", bytes: 64 * 1024 ** 3 };
        case "volumes_create": {
          const m = machineOf(args.machine);
          if (!m) return { outcome: "error", message: "the daemon knows no machine by that identity" };
          m.volumes.push({ name: args.name, bytes: args.bytes, created: new Date().toISOString(), mode: args.mode });
          ((trees[machineKey(args.machine)] ??= {}))[args.name] = [];
          return { outcome: "done" };
        }
        case "volumes_edit": {
          const v = volumesOf(args.machine).find((x) => x.name === args.name);
          if (v && args.bytes !== null) v.bytes = args.bytes;
          if (v && args.mode !== null) v.mode = args.mode;
          return { outcome: "done" };
        }
        case "volumes_delete": {
          const k = machineKey(args.machine);
          if (stats[k]?.[args.name]?.outcome === "error") return { outcome: "in_use" };
          const list = volumesOf(args.machine);
          list.splice(list.findIndex((x) => x.name === args.name), 1);
          return { outcome: "done" };
        }
        case "profile_get": {
          const mine = new Set(["me", ...agents.map((a) => a.name)]);
          const receipts = spaceRecs.flatMap((r) => r.moves.filter((m) => m.kind === "receipt" && mine.has(String((m.fields as Record<string, unknown>).to))).map((m) => ({ title: m.title, for_title: m.body.replace(/^Completed: /, ""), space: r.view.summary, to: String((m.fields as Record<string, unknown>).to), at: m.at })));
          const home = spaceOf("home-me");
          return { receipts, shows: home ? home.moves.filter((m) => m.kind === "show" && m.author === "me") : [], agents, machines, volumes: machines.flatMap((m) => m.volumes), home: "home-me" };
        }
        case "people_list": {
          const people = new Map<string, { name: string; is_agent: boolean; spaces: string[] }>();
          for (const r of spaceRecs) for (const m of r.view.members) {
            if (m.name === "me" || m.name === r.view.summary.joined_as) continue;
            const p = people.get(m.name) ?? { name: m.name, is_agent: m.is_agent, spaces: [] };
            p.spaces.push(r.view.summary.id);
            people.set(m.name, p);
          }
          return [...people.values()];
        }
        case "spaces_home":
          return "home-me";
        case "home_feed":
          return spaceRecs.flatMap((r) => r.moves.map((entry) => ({ space: r.view.summary, entry }))).sort((a, b) => b.entry.at.localeCompare(a.entry.at));
        case "spaces_list":
          return spaceRecs.map((r) => r.view.summary);
        case "spaces_get": {
          const r = spaceOf(args.id);
          if (!r) throw new Error("no such Space");
          return r.view;
        }
        case "spaces_feed": {
          const r = spaceOf(args.id);
          return r ? { outcome: "feed", moves: r.moves } : { outcome: "error", message: "no such Space" };
        }
        case "spaces_call": {
          const r = spaceOf(args.id);
          if (!r) return { outcome: "error", message: "no such Space" };
          const a = (args.arguments ?? {}) as Record<string, string>;
          const me = r.view.summary.joined_as;
          const now = new Date().toISOString();
          const push = (kind: string, title: string, body: string, state: string, parent: string | null, fields: Record<string, unknown> = {}) => {
            const id = `${kind}-${++moveN}`;
            r.moves.push({ id, kind, author: me, at: now, title, body, state, parent, fields });
            return id;
          };
          let line = "";
          switch (args.tool) {
            case "show": line = `Shown: ${a.title} (${push("show", a.title, a.body ?? "", "shown", null)})`; break;
            case "ask": line = `Asked: ${a.what} (${push("ask", a.what, "", "open", null, { needs: a.needs, ceiling: a.ceiling, who_may_serve: a.who_may_serve })})`; break;
            case "say": line = `Said (${push("say", "", a.body, "said", null)})`; break;
            case "reply": line = `Replied to ${a.move_id} (${push("reply", "", a.body, "said", a.move_id)})`; break;
            case "post_task": line = `Task posted: ${a.title} (${push("task", a.title, a.spec, "open", null, {})})`; break;
            case "claim": { const b = r.moves.find((m) => m.id === a.task_id); if (b) { b.state = "claimed"; (b.fields as Record<string, unknown>).claimed_by = me; push("claim", b.title, "", "claimed", b.id); line = `Claimed: ${b.title}`; } break; }
            case "deliver": { const b = r.moves.find((m) => m.id === a.task_id); if (b) { b.state = "delivered"; push("delivery", b.title, a.summary, "delivered", b.id); line = `Delivered: ${b.title}`; } break; }
            case "accept": { const b = r.moves.find((m) => m.id === a.task_id); if (b) { b.state = "done"; const f = b.fields as Record<string, unknown>; push("receipt", b.title, `Completed: ${b.title}`, "issued", b.id, { to: f.claimed_by }); line = `Accepted: ${b.title}`; } break; }
            case "post_offering": line = `Offered: ${a.title} (${push("offering", a.title, a.what, "offered", null, { pricing: a.pricing, terms: a.terms })})`; break;
            case "propose": line = `Proposed: ${a.direction} (${push("direction", a.direction, a.body ?? "", "open", null)})`; break;
            case "steer": { const d = r.moves.find((m) => m.id === a.direction_id); if (d) { const f = d.fields as Record<string, number>; f[a.move] = (f[a.move] ?? 0) + 1; push("steer", d.title, a.note ?? "", a.move, d.id); line = `Steered ${d.title}: ${a.move}`; } break; }
            case "synthesize": line = `Synthesis written (${push("synthesis", "Where it stands", a.body, "open", null)})`; break;
            default: return { outcome: "error", message: `this room has no verb called ${args.tool}` };
          }
          later(() => bump(args.id));
          return { outcome: "ok", text: line };
        }
        case "spaces_watch": {
          const id = `space-${++scope}`;
          spaceWatches.set(id, { id: args.id, ch: args.onEvent as Chan });
          return id;
        }
        case "spaces_host": {
          const i = args.input;
          const id = `space-${Date.now()}`;
          spaceRecs.push({ view: { summary: { id, title: i.title, kind: i.kind, host: { kind: "outgoing", address: "127.0.0.1:4640" }, mine: true, online: true, joined_as: "me" }, charter: i.charter, members: [{ name: "me", is_agent: false, joined: new Date().toISOString() }], tools: spaceRecs[0]?.view.tools ?? [] }, moves: [], invite: `diverge://space/${id}?host=outgoing:127.0.0.1:4640&key=${i.invite}` });
          return { outcome: "hosted", id };
        }
        case "spaces_join": {
          const m = /^diverge:\/\/space\/([^?]+)\?/.exec(String(args.invite));
          const r = m && spaceOf(m[1]);
          if (!r) return { outcome: "missing" };
          return { outcome: "joined", id: r.view.summary.id };
        }
        case "spaces_leave": {
          const at = spaceRecs.findIndex((r) => r.view.summary.id === args.id);
          if (at >= 0) spaceRecs.splice(at, 1);
          tabs = tabs.filter((t) => t.key !== `space:${args.id}`);
          generation++;
          emit("tabs://changed", snapshot());
          return null;
        }
        case "spaces_invite": {
          const r = spaceOf(args.id);
          return r?.invite ? { text: r.invite } : null;
        }
        case "knocks_watch": {
          knockCh = args.onEvent as Chan;
          later(() => { for (const k of knocks) knockCh?.onmessage({ event: "knock", knock: k }); });
          return `knocks-${++scope}`;
        }
        case "knocks_answer": {
          const at = knocks.findIndex((k) => k.knock_id === args.knockId);
          if (at >= 0) {
            const k = knocks.splice(at, 1)[0];
            const r = spaceOf(k.space);
            if (args.yes && r) r.view.members.push({ name: k.authorization.split(" as ")[1] ?? k.address, is_agent: false, joined: new Date().toISOString() });
          }
          return null;
        }
        case "cards_watch":
          cardCh = args.onEvent as Chan;
          later(() => { for (const c of cards) cardCh?.onmessage({ event: "card", card: c }); });
          return `cards-${++scope}`;
        case "cards_answer": {
          const at = cards.findIndex((c) => c.id === args.id);
          if (at >= 0) cards.splice(at, 1);
          cardCh?.onmessage({ event: "answered", id: args.id });
          return null;
        }
        case "door_tools":
          return fixture.door_tools;
        case "machines_names":
          return {};
        case "machines_rename":
          return { [args.identity.kind === "outgoing" ? `outgoing:${args.identity.address}` : `incoming:${args.identity.identity}`]: args.name };
        case "machines_list":
          return machines;
        case "machines_add": {
          const i = args.input;
          const identity = i.way === "dial" ? { kind: "outgoing", address: i.address } : { kind: "incoming_unbrokered", identity: i.identity };
          const m = { identity, volumes: [], volumes_problem: null, added: new Date().toISOString(), name: null } as MachineView;
          machines.push(m);
          return m;
        }
        case "machines_remove": {
          const at = machines.findIndex((m) => JSON.stringify(m.identity) === JSON.stringify(args.identity));
          if (at >= 0) machines.splice(at, 1);
          return null;
        }
        case "views_list":
          return views;
        case "views_save": {
          const v = { ...args.view, id: args.view.id || `view-${Date.now()}`, saved: new Date().toISOString() };
          const at = views.findIndex((x) => x.id === v.id);
          if (at >= 0) views[at] = v;
          else views.push(v);
          return v;
        }
        case "views_delete":
          views.splice(views.findIndex((x) => x.id === args.id), 1);
          return null;
        case "tabs_snapshot":
          return snapshot();
        case "tabs_open": {
          const key = keyOf(args.tab);
          if (!tabs.some((t) => t.key === key)) tabs = [...tabs, { key, tab: args.tab }];
          focused = key;
          generation++;
          return snapshot();
        }
        case "tabs_close": {
          const at = tabs.findIndex((t) => t.key === args.key);
          if (at >= 0) {
            tabs = tabs.filter((t) => t.key !== args.key);
            if (focused === args.key) focused = tabs[Math.min(at, tabs.length - 1)]?.key ?? null;
            generation++;
          }
          return snapshot();
        }
        case "tabs_focus":
          focused = args.key;
          generation++;
          return snapshot();
        default:
          throw new Error(`the browser preview has no answer for ${cmd}`);
      }
    },
    { shouldMockEvents: true },
  );
}

function matchesType(entry: LogEntry, wire: string): boolean {
  const map: Record<string, string> = {
    user_text_content: "user_text",
    assistant_text_content: "text",
    assistant_reasoning: "reasoning",
    assistant_tool_call: "tool_call",
    tool_response: "tool_response",
    usage: "usage",
    notification: "notification",
    error: "error",
    active: "active",
    inactive: "inactive",
    assistant_refusal: "refusal",
  };
  return map[wire] === entry.item.kind;
}
